//! ♻️ Existing cursor allocations retain recursive types and never execute closed-header Drop callbacks.
use super::*;
use std::{alloc::Layout,sync::atomic::{AtomicUsize,Ordering}};
use semio_framework_value_native_storage::NativeOwnedStorage;
struct Bank{left:RetainedCloneGrant,work:u64}
impl Bank{fn new()->Self{let f:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&f["stock"];Self{left:RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize},work:s["fuel"].as_u64().unwrap()}}fn grant(&self)->RetainedCloneGrant{assert!(self.left.maximum_items>0&&self.work>0);RetainedCloneGrant{maximum_items:1,..self.left}}fn post(&mut self,p:RetainedCloneProgress,work:u64){assert!(p.fits(self.left));self.left.maximum_items-=p.copied_items;self.left.maximum_copy_bytes-=p.copied_bytes;self.left.maximum_capacity_bytes-=p.retained_capacity_bytes;self.left.maximum_release_bytes-=p.released_bytes;self.work=self.work.checked_sub(work).unwrap();}fn step(&mut self,turn:crate::RetainedWorkOutcome)->RetainedCloneStep{let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());self.post(p,turn.work);turn.result.unwrap()}fn retire<T:crate::retirement::RetireOwned>(&mut self,value:T){let mut retirement_actual=None;let mut retirement_work=0;let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..10000{if owner.terminal_is_empty()&&retirement_actual.is_none(){return}let(result,heap)=observe(||{let turn=crate::source_fixture::close_step(&mut retirement_actual,self.grant(),self.work,owner.next_demand(4096),owner.next_computational_work(4096),|g,a|{let result=owner.step(g,a);crate::RetainedWorkOutcome{result,work:owner.last_turn_work()}});retirement_work=turn.work;turn.result});let work=retirement_work;let p=result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.post(p,work);result.unwrap();}panic!("recursive cursor fixture close depleted its unchanged finite stock")}}
impl Bank{fn original_step(&mut self,turn:crate::OriginalRetirementOutcome)->RetainedCloneStep{let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());self.post(p,turn.work);turn.result.unwrap()}fn clear_marker(&mut self,actual:&mut Option<usize>){if actual.is_none(){return}let(turn,heap)=observe(||crate::source_fixture::close_step(actual,self.grant(),self.work,Ok(Default::default()),Ok(0),|_,_|panic!("marker clear must precede a child effect")));assert_eq!(heap,(0,0));self.original_step(turn);assert!(actual.is_none());}}
fn observe<R>(f:impl FnOnce()->R)->(R,(usize,usize)){crate::observe_retirement_allocations(f)}
static POISON_DROPS:AtomicUsize=AtomicUsize::new(0);
struct PoisonHeader{byte:u8}
impl Drop for PoisonHeader{fn drop(&mut self){POISON_DROPS.fetch_add(1,Ordering::SeqCst);panic!("closed native header Drop callback was executed")}}
impl NativeReceiver<crate::DslValue,()> for PoisonHeader{
 fn capture_plan(&self)->Result<Option<semio_framework_value_native_decoding::native_decoding::NativeEffectCapturePlan>,ValueError>{Ok(None)}
 fn advance_work_demand(&self,_:RetainedCloneRef<'_,crate::DslValue>,_:usize,_:u64)->Result<u64,ValueError>{panic!("closed header algorithm called")}
 fn take_work_demand(&self)->Result<u64,ValueError>{panic!("closed header output called")}
 fn close_work_demand(&self,_:usize)->Result<u64,ValueError>{Ok(0)}
 fn demands(&self,_:RetainedCloneRef<'_,crate::DslValue>,_:usize,_:u64)->Result<RetirementDemand,ValueError>{panic!("closed header algorithm called")}
 fn advance(&mut self,_:RetainedCloneRef<'_,crate::DslValue>,_:&mut NativeDecodeControl<'_>,_:usize,_:u64,_:RetainedCloneGrant)->crate::RetainedWorkOutcome<RetainedCloneStep,crate::OriginalReceivingPrimary>{panic!("closed header algorithm called")}
 fn is_closing(&self)->bool{true}
 fn output_ready(&self)->bool{false}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{panic!("closed header output called")}
 fn take(&mut self,_:RetainedCloneGrant)->crate::RetainedWorkOutcome<Option<((),RetainedCloneProgress)>>{panic!("closed header output called")}
 fn has_pending_recovery(&self)->bool{false}
 fn pending_recovery(&mut self)->Option<crate::owned::NativeRecoveryLoan<'_>>{None}
 fn resume_recovery(&mut self,_:&mut NativeDecodeControl<'_>)->RetainedWorkOutcome<RetainedCloneProgress,crate::OriginalReceivingPrimary>{crate::owned::no_pending_recovery()}
 fn begin_close_admitted(&mut self,_permit:crate::owned::NativeClosePermit)->Result<(),ValueError>{Ok(())}
 fn close_demands(&self,_:usize)->Result<RetirementDemand,ValueError>{panic!("closed child cursor called")}
 fn close_work_demand(&self,_:usize)->Result<u64,ValueError>{panic!("closed child cursor called")}
 fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::OriginalRetirementOutcome{let _=effect.grant();panic!("closed child cursor called")}
 fn terminal_is_empty(&self)->bool{true}
}
#[test]fn actual_closed_receiver_header_moves_its_existing_allocation_and_skips_poison_drop(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let mut bank=Bank::new();let mut storage=NativeOwnedStorage::<PoisonHeader>::empty();let mut marker=None;let(turn,heap)=observe(||storage.reserve(bank.grant(),&mut marker));let p=bank.step(turn).progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(marker,Some(p.retained_capacity_bytes));assert_eq!(p.retained_capacity_bytes,Layout::new::<PoisonHeader>().size());bank.clear_marker(&mut marker);let mut input=Some(PoisonHeader{byte:17});let turn=storage.put_from(&mut input,bank.grant());bank.step(turn);assert!(input.is_none());let pointer=storage.address().unwrap();let mut retired:Option<Box<PoisonHeader>>=None;
 let d=native_receiver_backing_demands::<crate::DslValue,(),_>(&storage,&retired,4096).unwrap();let layout=f["handoff"].as_array().unwrap().iter().find(|r|r["pointerBytes"].as_u64()==Some(std::mem::size_of::<usize>()as u64)).unwrap();assert_eq!(d.copy_bytes,layout["copyBytes"].as_u64().unwrap()as usize);for denied in[RetainedCloneGrant{maximum_items:0,..bank.grant()},RetainedCloneGrant{maximum_depth:0,..bank.grant()}]{let(turn,heap)=observe(||close_native_receiver_backing::<crate::DslValue,(),_>(&mut storage,&mut retired,denied,&mut marker));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(storage.address(),Some(pointer));assert!(retired.is_none());}
 let(turn,heap)=observe(||close_native_receiver_backing::<crate::DslValue,(),_>(&mut storage,&mut retired,bank.grant(),&mut marker));assert_eq!(turn.work,f["moveWork"].as_u64().unwrap());assert_eq!(heap,(0,0));assert_eq!(bank.original_step(turn).progress().copied_bytes,d.copy_bytes);assert!(storage.terminal_is_empty());assert_eq!(retired.as_ref().unwrap().byte,17);assert_eq!(&**retired.as_ref().unwrap()as*const PoisonHeader as usize,pointer);
 let d=native_receiver_backing_demands::<crate::DslValue,(),_>(&storage,&retired,4096).unwrap();assert_eq!(d.release_bytes,Layout::new::<PoisonHeader>().size());for denied in[RetainedCloneGrant{maximum_items:0,..bank.grant()},RetainedCloneGrant{maximum_depth:0,..bank.grant()},RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..bank.grant()}]{let(turn,heap)=observe(||close_native_receiver_backing::<crate::DslValue,(),_>(&mut storage,&mut retired,denied,&mut marker));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert!(retired.is_some());assert_eq!(POISON_DROPS.load(Ordering::SeqCst),0);}
 let(turn,heap)=observe(||close_native_receiver_backing::<crate::DslValue,(),_>(&mut storage,&mut retired,bank.grant(),&mut marker));assert_eq!(turn.work,f["freeWork"].as_u64().unwrap());let p=bank.original_step(turn).progress();assert_eq!(heap,(0,p.released_bytes));assert_eq!(p.released_bytes,Layout::new::<PoisonHeader>().size());assert!(retired.is_none());assert_eq!(POISON_DROPS.load(Ordering::SeqCst),f["poisonDropCalls"].as_u64().unwrap()as usize);assert_eq!(close_native_receiver_backing::<crate::DslValue,(),_>(&mut storage,&mut retired,Default::default(),&mut marker).work,0);
}
